/** Problems of `data` against a JSON Schema subset (object/properties, number/integer ranges, boolean, string). */
create or replace function public.json_problems(sch jsonb, data jsonb, path text default '')
returns setof text language plpgsql immutable set search_path = '' as $$
declare
  t text := sch ->> 'type';
  k text;
  v jsonb;
  num numeric;
begin
  if data is null or jsonb_typeof(data) = 'null' then
    return;
  end if;
  if t = 'object' then
    if jsonb_typeof(data) <> 'object' then return next path || ': expected an object'; return; end if;
    for k, v in select * from jsonb_each(data) loop
      if sch -> 'properties' ? k then
        return query select * from public.json_problems(sch -> 'properties' -> k, v, case when path = '' then k else path || '.' || k end);
      else
        return next (case when path = '' then k else path || '.' || k end) || ': unknown field';
      end if;
    end loop;
  elsif t in ('number', 'integer') then
    if jsonb_typeof(data) <> 'number' then return next path || ': expected a number'; return; end if;
    num := data::text::numeric;
    if t = 'integer' and num <> trunc(num) then return next path || ': expected an integer'; end if;
    if sch ? 'minimum' and num < (sch ->> 'minimum')::numeric then return next path || ': below ' || (sch ->> 'minimum'); end if;
    if sch ? 'maximum' and num > (sch ->> 'maximum')::numeric then return next path || ': above ' || (sch ->> 'maximum'); end if;
  elsif t = 'boolean' then
    if jsonb_typeof(data) <> 'boolean' then return next path || ': expected true/false'; end if;
  elsif t = 'string' then
    if jsonb_typeof(data) <> 'string' then return next path || ': expected text'; end if;
  end if;
end $$;

create or replace function public.config_problems(data jsonb)
returns text[] language sql stable security definer set search_path = '' as $$
  select coalesce(array_agg(p), '{}') from public.json_problems((select schema from public.config_schema where id = 1), data) as p
$$;

/** Published versions are immutable; publish and rollback both create a new version. */
create or replace function public.balance_configs_immutable()
returns trigger language plpgsql as $$
begin
  if old.status = 'published' and (new.data is distinct from old.data or new.version is distinct from old.version) then
    raise exception 'PUBLISHED_CONFIG_IS_IMMUTABLE';
  end if;
  return new;
end $$;
create trigger balance_configs_no_edit before update on public.balance_configs for each row execute function public.balance_configs_immutable();
create trigger balance_configs_audit after insert or update on public.balance_configs for each row execute function public.audit_trigger();

create or replace function public.publish_config(p_data jsonb, p_note text default '')
returns int language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := public.assert_admin();
  problems text[] := public.config_problems(p_data);
  v int;
begin
  if array_length(problems, 1) > 0 then
    raise exception 'CONFIG_INVALID: %', array_to_string(problems[1:10], '; ') using errcode = '22023';
  end if;
  select coalesce(max(version), 0) + 1 into v from public.balance_configs;
  insert into public.balance_configs (version, data, status, note, created_by, published_at)
  values (v, p_data || jsonb_build_object('version', v), 'published', coalesce(p_note, ''), uid, now());
  return v;
end $$;

create or replace function public.rollback_config(p_version int, p_note text default '')
returns int language plpgsql security definer set search_path = '' as $$
declare
  d jsonb;
begin
  perform public.assert_admin();
  select data into d from public.balance_configs where version = p_version;
  if d is null then raise exception 'NO_SUCH_VERSION' using errcode = 'P0002'; end if;
  return public.publish_config(d - 'version', coalesce(nullif(p_note, ''), 'rollback to v' || p_version));
end $$;

/** Players fetch a published version (or the latest). */
create or replace function public.get_config(p_version int default null)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('version', c.version, 'data', c.data)
  from public.balance_configs c
  where c.status = 'published' and c.version = coalesce(p_version, public.current_config_version())
$$;

create or replace function public.set_flag(p_key text, p_value jsonb)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform public.assert_admin();
  update public.feature_flags set value = p_value, updated_at = now() where key = p_key;
  if not found then raise exception 'UNKNOWN_FLAG' using errcode = '22023'; end if;
end $$;

revoke all on function public.publish_config(jsonb, text) from public, anon;
revoke all on function public.rollback_config(int, text) from public, anon;
revoke all on function public.set_flag(text, jsonb) from public, anon;
grant execute on function public.publish_config(jsonb, text) to authenticated;
grant execute on function public.rollback_config(int, text) to authenticated;
grant execute on function public.set_flag(text, jsonb) to authenticated;
grant execute on function public.get_live_state() to anon, authenticated;
grant execute on function public.get_config(int) to anon, authenticated;
